insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('43fdd7c5-32da-476a-baf6-ceb00e01ae70', 'situacion', 'DONALD S1 · Pregunta 1', 'ctx-sit', '<p>Se estudiaron los salarios de 200 personas; 164 tenían deudas de tarjeta de crédito. La tabla 1 distribuye las 200 personas según salario y sexo. La tabla 2 indica cuántas personas destinan el 15 % o el 35 % del salario a cuotas mensuales.</p><div class="ctx-datos" role="region" aria-label="Porcentaje de personas por salario" tabindex="0"><table class="ctx-table ctx-table-nativa"><caption>Porcentaje de personas por salario</caption><thead><tr><th scope="col">Salario</th><th scope="col">Hombres</th><th scope="col">Mujeres</th><th scope="col">Total</th></tr></thead><tbody><tr><th scope="row">$1.000.000</th><td>2 %</td><td>18 %</td><td>40</td></tr><tr><th scope="row">$1.500.000</th><td>15 %</td><td>10 %</td><td>50</td></tr><tr><th scope="row">$2.000.000</th><td>21 %</td><td>14 %</td><td>70</td></tr><tr><th scope="row">$3.000.000</th><td>12 %</td><td>8 %</td><td>40</td></tr></tbody></table></div><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Porcentaje destinado a cuotas</th><th scope="col">$1.000.000</th><th scope="col">$1.500.000</th><th scope="col">$2.000.000</th><th scope="col">$3.000.000</th></tr></thead><tbody><tr><th scope="row">15 %</th><td>10</td><td>15</td><td>25</td><td>10</td></tr><tr><th scope="row">35 %</th><td>24</td><td>24</td><td>31</td><td>25</td></tr><tr><th scope="row">Total de personas por salario</th><td>34</td><td>39</td><td>56</td><td>35</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('361bfcda-bd86-4556-b3c5-1ad4675b8ec9', 'situacion', 'DONALD S1 · Pregunta 3', 'ctx-sit', '<p>Se estudiaron los salarios de 200 personas; 164 tenían deudas de tarjeta de crédito. La tabla 1 distribuye las 200 personas según salario y sexo. La tabla 2 indica cuántas personas destinan el 15 % o el 35 % del salario a cuotas mensuales.</p><div class="ctx-datos" role="region" aria-label="Porcentaje de personas por salario" tabindex="0"><table class="ctx-table ctx-table-nativa"><caption>Porcentaje de personas por salario</caption><thead><tr><th scope="col">Salario</th><th scope="col">Hombres</th><th scope="col">Mujeres</th><th scope="col">Total</th></tr></thead><tbody><tr><th scope="row">$1.000.000</th><td>2 %</td><td>18 %</td><td>40</td></tr><tr><th scope="row">$1.500.000</th><td>15 %</td><td>10 %</td><td>50</td></tr><tr><th scope="row">$2.000.000</th><td>21 %</td><td>14 %</td><td>70</td></tr><tr><th scope="row">$3.000.000</th><td>12 %</td><td>8 %</td><td>40</td></tr></tbody></table></div><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Porcentaje destinado a cuotas</th><th scope="col">$1.000.000</th><th scope="col">$1.500.000</th><th scope="col">$2.000.000</th><th scope="col">$3.000.000</th></tr></thead><tbody><tr><th scope="row">15 %</th><td>10</td><td>15</td><td>25</td><td>10</td></tr><tr><th scope="row">35 %</th><td>24</td><td>24</td><td>31</td><td>25</td></tr><tr><th scope="row">Total de personas por salario</th><td>34</td><td>39</td><td>56</td><td>35</td></tr></tbody></table></div><p>Un analista promedia los porcentajes: (15 % + 35 %)/2 = 25 %. Luego promedia los usuarios: (25 + 31)/2 = 28. Finalmente calcula $2.000.000×28×25 % = $14.000.000.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('7630ef7c-c111-4728-9f77-470371f392e0', 'situacion', 'DONALD S1 · Pregunta 4', 'ctx-sit', '<p>Para estudiar correlación entre dos conjuntos con igual número de datos se proponen diferencias respecto a sus promedios, productos de esas diferencias y desviaciones estándar. La tabla muestra cinco personas.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Nombre</th><th scope="col">Peso (kg)</th><th scope="col">Edad</th><th scope="col">Color de ojos</th></tr></thead><tbody><tr><th scope="row">Paola</th><td>60</td><td>30</td><td>Verde</td></tr><tr><th scope="row">Andrea</th><td>50</td><td>23</td><td>Azul</td></tr><tr><th scope="row">Gloria</th><td>55</td><td>50</td><td>Café</td></tr><tr><th scope="row">Luis</th><td>52</td><td>18</td><td>Azul</td></tr><tr><th scope="row">Mario</th><td>53</td><td>20</td><td>Café</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('8db090bc-2c0a-461e-9763-d73b8dba0865', 'situacion', 'DONALD S1 · Pregunta 5', 'ctx-sit', '<p>En un concierto se retira el 50 % de los asistentes después de una hora y el 30 % del total inicial después de dos horas. Los 100 restantes permanecen hasta el final.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e0e7bd27-f036-4100-815d-72f6b2530cfc', 'situacion', 'DONALD S1 · Pregunta 6', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q06-petroleo.webp" alt="Consumo de petróleo per cápita en 2013 de Colombia, Venezuela, Ecuador, Perú, Chile, Bolivia y Argentina." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('bd220af9-a364-40ee-8202-5172074dc8d0', 'situacion', 'DONALD S1 · Pregunta 7', 'ctx-sit', '<p>La tabla resume costos de fabricación, precios de venta y unidades vendidas de cuatro tipos de calzado en 2014.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Producto</th><th scope="col">Costo de fabricación</th><th scope="col">Precio de venta</th><th scope="col">Unidades vendidas</th></tr></thead><tbody><tr><th scope="row">Botas</th><td>$30.000</td><td>$32.000</td><td>500</td></tr><tr><th scope="row">Zapatillas</th><td>$25.000</td><td>$30.000</td><td>800</td></tr><tr><th scope="row">Zapatos deportivos</th><td>$35.000</td><td>$35.000</td><td>2.000</td></tr><tr><th scope="row">Zapatos formales</th><td>$50.000</td><td>$80.000</td><td>1.200</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('1b87f261-f663-48f5-a304-df2fdddf8bd0', 'situacion', 'DONALD S1 · Pregunta 8', 'ctx-sit', '<p>En una empresa con una cantidad par de trabajadores, la mediana de los salarios es 2 SMLV. Alguien afirma que la mitad de los trabajadores gana exactamente ese sueldo.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('00fece41-df8b-4dbf-b9f5-2c9d88ecaf33', 'situacion', 'DONALD S1 · Pregunta 9', 'ctx-sit', '<p>Para elegir un buen día de pesca se busca poca gente en el lago y baja probabilidad de lluvia.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('c9798f18-d740-490f-844f-e4549cc5c6cb', 'situacion', 'DONALD S1 · Pregunta 10', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q10-edades.webp" alt="Once estudiantes de la banda: edades 14, 15, 41, 12, 12, 13, 14, 14, 10, 11, 10." loading="lazy"></figure><p>Se propone ordenar por edad de mayor a menor, seleccionar los dos estudiantes centrales y promediar sus edades.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('57a23efe-359e-42b3-8979-46e55111ff82', 'situacion', 'DONALD S1 · Pregunta 11', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q11-limpieza.webp" alt="Itinerario 1: el disco llega al 100 % de limpieza en dos días. Itinerario 2: llega al 50 % en cinco días." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('90b14b42-d522-40a7-9bed-ee918e408bfc', 'situacion', 'DONALD S1 · Pregunta 12', 'ctx-sit', '<p>Se comparan las tasas de bilingüismo por edad de dos ciudades, expresadas por cada mil habitantes.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q12-bilinguismo.webp" alt="Ciudad 1 por grupos 10–19, 20–24, 25–34, 35–44 y 45 o más: 110, 75, 120, 85, 90. Ciudad 2: 130, 75, 130, 95, 100." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('7a5fb772-e87e-4720-9b78-d74b40b8f82d', 'situacion', 'DONALD S1 · Pregunta 13', 'ctx-sit', '<p>Una casa de cambio compra dólares a $2.700 y los vende a $2.850. Un turista cambia 2.000 dólares a pesos, gasta parte del dinero y quiere recuperar dólares con el sobrante. Multiplica 2.000×2.700, resta lo gastado y divide el sobrante entre 2.700.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('10eda7a7-7ba6-4f0d-9df1-005f73cd2db2', 'situacion', 'DONALD S1 · Pregunta 14', 'ctx-sit', '<p>Se suelta un carro desde distintas alturas h en una montaña rusa y se observa si pasa por M y llega a F. Se encuentra que desde una altura menor a 2,5 m no logra dar la vuelta al segmento circular.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q14-montana.webp" alt="Rampa de altura h seguida de un lazo circular de radio 1 m, con M arriba y F al final." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('a6c8dda3-6e1e-4af5-a908-6d40166a133d', 'situacion', 'DONALD S1 · Pregunta 15', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q15-rendimiento.webp" alt="Nueve ensayos: muy bajo, muy bajo, bajo, bajo, bajo, bajo, medio, medio, alto. La gráfica circular resume 22 %, 45 %, 22 % y 11 %." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('b1f77d1f-0aa8-4c75-a19a-469112d13bf7', 'situacion', 'DONALD S1 · Pregunta 16', 'ctx-sit', '<div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Dato del campeonato</th><th scope="col">Valor</th></tr></thead><tbody><tr><th scope="row">Número de saltos realizados</th><td>90</td></tr><tr><th scope="row">Cantidad de atletas</th><td>30</td></tr><tr><th scope="row">Menor distancia de un salto</th><td>11,5 metros</td></tr><tr><th scope="row">Mayor distancia de un salto</th><td>14,2 metros</td></tr></tbody></table></div><figure class="ctx-fig"><img src="img/figuras/mat/do1-q16-quintiles.webp" alt="Los quintiles delimitan distancias de 12,4; 12,9; 13,3 y 13,5 metros." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('3e26379a-8f91-4078-86b1-fc40cc4efd33', 'situacion', 'DONALD S1 · Pregunta 17', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q17-mapa.webp" alt="Camino desde la entrada occidental hacia el sur; cada casilla mide x metros de lado." loading="lazy"></figure><p>Instrucciones: 1. Oriente 6x. 2. Sur x. 3. Oriente 2x. 4. Sur 2x. 5. Oriente 4x. 6. Sur 2x. El paso 1 es correcto.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('6f8fac2f-32c4-4215-8286-a21d7e81d36e', 'situacion', 'DONALD S1 · Pregunta 18', 'ctx-sit', '<div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Mes</th><th scope="col">Ventas (millones de $)</th></tr></thead><tbody><tr><th scope="row">Enero</th><td>1.000</td></tr><tr><th scope="row">Febrero</th><td>6.000</td></tr><tr><th scope="row">Marzo</th><td>3.500</td></tr><tr><th scope="row">Abril</th><td>1.500</td></tr><tr><th scope="row">Mayo</th><td>4.000</td></tr><tr><th scope="row">Junio</th><td>3.500</td></tr></tbody></table></div>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('2f362f41-d26a-4cec-ab43-54f69e18d702', 'situacion', 'DONALD S1 · Pregunta 19', 'ctx-sit', '<p>El aviso ofrece un descuento del 10 % en el impuesto de vehículos por pago anticipado.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q19-aviso.webp" alt="Impuesto de vehículos: 10 % de descuento hasta el 13 de mayo; último pago sin descuento el 22 de junio." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('dde1b803-207d-4442-8956-4f5794e529e4', 'situacion', 'DONALD S1 · Pregunta 20', 'ctx-sit', '<p>Una tienda clasifica las piezas de vajilla con una, dos o tres estrellas; más estrellas significan mejor calidad.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q20-vajilla.webp" alt="Precios por 1, 2 y 3 estrellas: platos redondos $2.500, $4.000, $9.000; hondos $1.500, $4.000, $4.000; vasos $1.000 en las tres calidades." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e3772c1f-c99d-419d-8990-bf7f4e73a81d', 'situacion', 'DONALD S1 · Pregunta 21', 'ctx-sit', '<p>Una tienda clasifica las piezas de vajilla con una, dos o tres estrellas; más estrellas significan mejor calidad.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q20-vajilla.webp" alt="Precios por 1, 2 y 3 estrellas: platos redondos $2.500, $4.000, $9.000; hondos $1.500, $4.000, $4.000; vasos $1.000 en las tres calidades." loading="lazy"></figure><p>Un bono permite multiplicar por 0,9 el costo de las piezas de una estrella y por 0,8 el de las piezas de dos o tres estrellas. Un cliente compra cinco platos hondos de tres estrellas y diez vasos de una estrella.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('31652342-6983-4090-a23a-4acd6b1b77cc', 'situacion', 'DONALD S1 · Pregunta 23', 'ctx-sit', '<p>Lucy ordena 40 valores numéricos distintos de menor a mayor. Calcula Q₂ como promedio de los dos centrales; Q₁ como mediana de la mitad inferior; Q₃ como mediana de la mitad superior.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e6a69195-bbfb-4272-99ff-115a1a2e5cb3', 'situacion', 'DONALD S1 · Pregunta 24', 'ctx-sit', '<p>Se reparten 50 millones de pesos entre tres puestos de una competencia. El primero recibe 1/2 del total, el segundo 2/5 y el tercero el resto.</p>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('4918dff0-ee76-4c7e-b236-ef803b1dfe8e', 'situacion', 'DONALD S1 · Pregunta 25', 'ctx-sit', '<p>La entrada a la torre de Pisa cuesta 17 euros; con reserva se pagan 5,5 euros adicionales. La tabla muestra los visitantes de una semana.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q25-entradas.webp" alt="Sin reserva de lunes a domingo: 300, 300, 500, 700, 300, 300, 700; con reserva: 700, 800, 200, 600, 500, 500, 600." loading="lazy"></figure><figure class="ctx-fig"><img src="img/figuras/mat/do1-q25-proceso.webp" alt="Sumar visitantes por modalidad, multiplicar por 22,5 o por 17 según corresponda y comparar las recaudaciones." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('005488b9-895e-4997-a21b-cd8689c50d07', 'situacion', 'DONALD S1 · Pregunta 26', 'ctx-sit', '<p>La torre está inclinada 4° respecto a la vertical.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q26-torre.webp" alt="Torre inclinada 4° hacia la derecha de la vertical, con ángulo desconocido respecto al suelo horizontal." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('e612197c-a1ee-4043-ad3e-9ee8b0dcf668', 'situacion', 'DONALD S1 · Pregunta 27', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q27-vitral.webp" alt="Vitral cuadrado sobre cuadrícula, dividido en zonas 1 y 2 a la izquierda y 3 y 4 a la derecha." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('fe48f504-a6c8-405d-8e8a-ad7fe9efb0f2', 'situacion', 'DONALD S1 · Pregunta 28', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q28-carga.webp" alt="Avión 1 con capacidad de 12 toneladas, avión 2 de 10. Cuatro cajas pesan 8, 7, 5 y 2 toneladas." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('6cd24738-7ba4-4dc8-afca-0f8d8176fb27', 'situacion', 'DONALD S1 · Pregunta 29', 'ctx-sit', '<p>Se quiere calcular la distancia que recorre la punta del minutero desde las 12:00 hasta las 3:00. Se propone hallar el número de vueltas, calcular 2πr y multiplicar ambos resultados.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q29-relojes.webp" alt="Relojes a las 12:00 y a las 3:00; el minutero mide 5 cm." loading="lazy"></figure>');
insert into public.contextos (id, tipo, etiqueta, clase, contenido) values ('6aa2f392-6a3f-4812-abfe-8397c709daa3', 'situacion', 'DONALD S1 · Pregunta 30', 'ctx-sit', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q30-evolucion.webp" alt="Entre 2000 y 2010 los alumnos bajan de 40.000 a 30.000 y los profesores suben de 2.000 a 3.000." loading="lazy"></figure>');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'e4f2df53-2279-48ea-ac12-862b2ca71e4a', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'proporcionalidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '43fdd7c5-32da-476a-baf6-ceb00e01ae70', 'Proporcionalidad y porcentajes',
  'Un analista afirma que entre las 25 personas que ganan $2.000.000 y destinan el 15 % a la tarjeta hay (42/70)×25 = 15 hombres y (28/70)×25 = 10 mujeres. ¿Qué debe cumplirse para que sea verdadero?',
  array['La proporción de hombres y mujeres del grupo de 25 debe ser la misma que en el grupo de 70 personas con ese salario.', 'La distribución de hombres y mujeres con salario de $2.000.000 debe ser equitativa.', 'El número de personas con ese salario que pagan tarjeta debe ser 70.', 'Debe haber 21 hombres y 14 mujeres con ese salario.'],
  'Una proporción del grupo completo no se puede atribuir automáticamente a un subgrupo.', 'publicada', 'modelo', '1198fd6b33ca848d7f04cf769a1a3a6f', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e4f2df53-2279-48ea-ac12-862b2ca71e4a', 0, 'Se aplican al subgrupo las proporciones 42/70 y 28/70 del grupo completo. Eso solo es válido si ambos grupos conservan la misma distribución por sexo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'f5f44e77-470e-4f97-9ca4-fb0ea591e56f', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'proporcionalidad'),
  (select id from public.lotes where codigo = '2026-B'),
  '43fdd7c5-32da-476a-baf6-ceb00e01ae70', 'Proporcionalidad y porcentajes',
  'Para quienes destinan el 15 % a cuotas, se multiplica el salario por 0,15. ¿Qué comparación es correcta?',
  array['Quien gana $3.000.000 paga $150.000 más que quien gana $2.000.000.', 'Quien gana $3.000.000 paga $100.000 más que quien gana $2.000.000.', 'Quien gana $1.500.000 paga $150.000 más que quien gana $1.000.000.', 'Quien gana $1.500.000 paga $100.000 más que quien gana $1.000.000.'],
  'También puedes calcular el 15 % de la diferencia entre los salarios.', 'publicada', 'modelo', '04e089c9815a23531a2148968bbf7600', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f5f44e77-470e-4f97-9ca4-fb0ea591e56f', 0, 'El 15 % de 3 millones es 450.000 y el de 2 millones es 300.000: diferencia de 150.000. Entre los otros salarios, la diferencia de cuotas es 75.000.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'da3c8add-09c0-4e1a-bd90-01851150d638', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  '361bfcda-bd86-4556-b3c5-1ad4675b8ec9', 'Estadística descriptiva',
  '¿Por qué ese procedimiento no da el ingreso mensual total por cuotas de las personas con salario de $2.000.000?',
  array['Usó valores de otra categoría salarial y debe rectificarlos.', 'Debió promediar solo los porcentajes y sumar todas las personas del rango.', 'Solo contó a 56 personas y debe calcularlo para 70.', 'Promedió innecesariamente los registros: debe calcular por separado el aporte de cada grupo y sumarlos.'],
  'Multiplica cantidad de personas por cuota de cada grupo y luego suma.', 'publicada', 'modelo', '7e31f5795afbe91bbd5db806ebc02b9d', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('da3c8add-09c0-4e1a-bd90-01851150d638', 3, 'El total es 25×2.000.000×0,15 + 31×2.000.000×0,35 = 29.200.000. Los 14 restantes no aparecen como deudores de tarjeta. Multiplicar promedios no sustituye la suma de los aportes.');

