insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6d357fd8-e9f4-4810-8282-721694c0f0fe', 0, 'Queda el 100 % − 50 % − 30 % = 20 % del total. Si ese 20 % son 100 personas, el total es 100/0,20 = 500.');

