insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1dabbc8e-7ac3-452d-a2c0-ff491b7cdbb7', 3, 'En orden creciente aparecen Colombia, Perú, Bolivia, Ecuador, Argentina, Chile y Venezuela. El cuarto de siete datos es Ecuador.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '248540a5-7760-423c-95d4-0b7205e9abd8', 'mat',
