insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('248540a5-7760-423c-95d4-0b7205e9abd8', 1, 'El mayor precio de venta es $80.000 y corresponde a los zapatos formales. Las botas tienen menos unidades vendidas y las zapatillas el menor precio.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'fd8d8955-0ee9-49e0-9b44-f0e19f24f370', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  '1b87f261-f663-48f5-a304-df2fdddf8bd0', 'Estadística descriptiva',
  '¿Por qué esa afirmación puede ser incorrecta?',
  array['Cada valor se escoge una sola vez y no se cuentan las personas de cada salario.', 'Puede haber personas que ganan 2 SMLV y que no son los datos centrales usados para hallar la mediana.', 'La mediana representa el máximo sueldo que gana la mitad de los empleados al ordenar los datos.', 'La mediana representa lo que gana la mayoría de empleados.'],
  'Mediana describe posición; moda describe frecuencia.', 'publicada', 'modelo', '90dee3d018bfe109497cf2cf9a6b77c2', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('fd8d8955-0ee9-49e0-9b44-f0e19f24f370', 1, 'La mediana depende de la posición central, no de cuántas veces se repite un sueldo. Puede haber más, menos o ninguna persona con el valor exacto de la mediana.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
