  array['<div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Día de la semana</th><th scope="col">Número de visitantes</th><th scope="col">Temperatura ambiente (°C)</th></tr></thead><tbody><tr><th scope="row">Lunes</th><td>4</td><td>30</td></tr><tr><th scope="row">Martes</th><td>2</td><td>20</td></tr><tr><th scope="row">Miércoles</th><td>5</td><td>28</td></tr><tr><th scope="row">Jueves</th><td>7</td><td>18</td></tr></tbody></table></div>', '<div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Meses de vacaciones</th><th scope="col">Número de visitantes</th><th scope="col">Temperatura ambiente (°C)</th></tr></thead><tbody><tr><th scope="row">Enero</th><td>4</td><td>30</td></tr><tr><th scope="row">Abril</th><td>2</td><td>20</td></tr><tr><th scope="row">Junio</th><td>5</td><td>28</td></tr><tr><th scope="row">Julio</th><td>7</td><td>18</td></tr></tbody></table></div>', '<div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Día de la semana</th><th scope="col">Número de visitantes</th><th scope="col">Probabilidad de lluvia (%)</th></tr></thead><tbody><tr><th scope="row">Lunes</th><td>4</td><td>20</td></tr><tr><th scope="row">Martes</th><td>2</td><td>80</td></tr><tr><th scope="row">Miércoles</th><td>5</td><td>40</td></tr><tr><th scope="row">Jueves</th><td>7</td><td>90</td></tr></tbody></table></div>', '<div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Meses de vacaciones</th><th scope="col">Número de visitantes</th><th scope="col">Probabilidad de lluvia (%)</th></tr></thead><tbody><tr><th scope="row">Enero</th><td>4</td><td>20</td></tr><tr><th scope="row">Abril</th><td>2</td><td>80</td></tr><tr><th scope="row">Junio</th><td>5</td><td>40</td></tr><tr><th scope="row">Julio</th><td>7</td><td>90</td></tr></tbody></table></div>'],
  'Empareja cada criterio de decisión con una columna.', 'publicada', 'modelo', '15511fd9696656ff010a20b15841365b', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('43c47545-d146-4a55-a554-bbc54ff24d46', 2, 'La decisión es sobre un día y depende tanto de visitantes como de lluvia. La tabla por día que contiene esas dos variables reúne toda la información pertinente.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
