insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2f9912e3-a743-4ab9-8e3b-3d8052578c52', 1, 'Hay once datos, una cantidad impar. La mediana es el sexto dato ordenado, 13, sin promediar dos posiciones. Ordenar en sentido ascendente o descendente lleva al mismo centro.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
