  'Una persona requiere una limpieza completa que dure cinco días y elige el itinerario 2. ¿Cómo es su selección?',
  array['Incorrecta, porque no cumple ni porcentaje ni duración.', 'Correcta, porque porcentaje y tiempo se relacionan linealmente.', 'Incorrecta, porque no cumple el porcentaje de limpieza requerido.', 'Correcta, porque el tiempo requerido está indicado en la gráfica.'],
  'Verifica todas las condiciones, no únicamente el tiempo.', 'publicada', 'modelo', '6d54ffed2e182431ea93ffb04cf54f8c', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('87cbb312-9ece-4dd4-bd09-7095b15610b7', 2, 'A los cinco días el itinerario 2 solo ha limpiado el 50 % del disco. Coincidir en duración no satisface la exigencia de limpieza completa.');

