insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4b8f3436-976c-4e2b-afb6-93937c4c3a29', 1, 'La tabla permite saber la clasificación de cada ensayo y su orden. La gráfica resume las frecuencias y pierde esa correspondencia ensayo por ensayo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '7a65517a-2210-42b7-a989-1c5d1a532083', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  'b1f77d1f-0aa8-4c75-a19a-469112d13bf7', 'Estadística descriptiva',
  '¿Cuál gráfica representa correctamente la información sobre las distancias de los saltos?',
  array['<figure class="ctx-fig"><img src="img/figuras/mat/do1-q16-a.webp" alt="Cinco intervalos entre 11,5 y 14,2 m, con 30 saltos en cada uno." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q16-b.webp" alt="Cinco intervalos entre 12 y 14 m, con 30 saltos en cada uno." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q16-c.webp" alt="Cinco intervalos entre 11,5 y 14,2 m, con 18 saltos en cada uno." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q16-d.webp" alt="Cinco intervalos entre 12 y 14 m, con 18 saltos en cada uno." loading="lazy"></figure>'],
  'Los quintiles dividen el número de observaciones, no el número de atletas.', 'publicada', 'modelo', 'eb7cf937554436cb763670c34a950acd', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7a65517a-2210-42b7-a989-1c5d1a532083', 2, 'Los quintiles separan el conjunto en cinco partes de igual frecuencia: 90/5 = 18 saltos por intervalo. Los extremos deben conservar la mínima de 11,5 m y la máxima de 14,2 m.');

