  array['En el 6, porque debería seguir de frente.', 'En el 2, porque debe avanzar 2x en lugar de x.', 'En el 5, porque al girar al oriente chocaría con la pared.', 'En el 3, porque debe ir al occidente.'],
  'Recorre las instrucciones sobre la cuadrícula, una por una.', 'publicada', 'modelo', '86d40c6d746423732fe15a3842fc1a40', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f6fe6c7d-eccd-4001-ad56-876e92f65397', 2, 'Después de bajar por el extremo derecho del camino, el tramo horizontal va hacia la izquierda, es decir, al occidente. El paso 5 indica el sentido contrario.');

