  '2f362f41-d26a-4cec-ab43-54f69e18d702', 'Proporcionalidad y porcentajes',
  '¿Qué gráfica relaciona el impuesto sin descuento con el valor que se paga con descuento?',
  array['<figure class="ctx-fig"><img src="img/figuras/mat/do1-q19-a.webp" alt="Recta que llega aproximadamente a 80 cuando el valor sin descuento es 800." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q19-b.webp" alt="Recta que llega a 720 cuando el valor sin descuento es 800." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q19-c.webp" alt="Recta cuya pendiente es aproximadamente 0,8." loading="lazy"></figure>', '<figure class="ctx-fig"><img src="img/figuras/mat/do1-q19-d.webp" alt="Recta cuyo valor con descuento es mayor que el valor original." loading="lazy"></figure>'],
  'El valor pagado es el total menos el descuento.', 'publicada', 'modelo', '5bada41795ad92766688a4ce44efc5e2', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1213c4da-72d3-4a4c-bad2-8670a939413b', 1, 'Un descuento del 10 % deja por pagar el 90 %: y = 0,9x. Si el impuesto original es 800 mil pesos, se pagan 720 mil.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '6c18eade-7266-4fe1-89c3-095303c46a27', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'lectura-de-graficas'),
  (select id from public.lotes where codigo = '2026-B'),
  'dde1b803-207d-4442-8956-4f5794e529e4', 'Interpretación de datos',
  'Alguien afirma que las piezas con más estrellas siempre son más costosas. ¿Qué ejemplo contradice la afirmación?',
  array['Las piezas de dos estrellas tienen el mismo precio.', 'Las piezas de tres estrellas tienen precios decrecientes.', 'Los vasos tienen el mismo precio sin importar la calidad.', 'Los platos hondos aumentan el precio según la calidad.'],
  'Una afirmación que dice «siempre» se refuta con un solo contraejemplo.', 'publicada', 'modelo', '511dc896dce6ef45090f214b848fc8d4', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6c18eade-7266-4fe1-89c3-095303c46a27', 2, 'Los vasos conservan el precio de $1.000 con una, dos o tres estrellas. Por tanto, mejorar la calidad no siempre aumenta el precio.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '3a46317c-5409-4ea2-bf72-ad0704af3451', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'proporcionalidad'),
  (select id from public.lotes where codigo = '2026-B'),
  'e3772c1f-c99d-419d-8990-bf7f4e73a81d', 'Proporcionalidad y porcentajes',
  '¿Cuál es el valor total de la compra con el bono?',
  array['$24.000.', '$25.000.', '$26.000.', '$27.000.'],
  'Aplica a cada grupo el factor de descuento correspondiente.', 'publicada', 'modelo', 'd4caa7f4cece7da13c812b645fa6bf48', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3a46317c-5409-4ea2-bf72-ad0704af3451', 1, 'Los platos cuestan 5×4.000×0,8 = 16.000 y los vasos 10×1.000×0,9 = 9.000. El total es 25.000 pesos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '39bd7991-e03d-4256-9b5d-7d8eaa616bde', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  'dde1b803-207d-4442-8956-4f5794e529e4', 'Estadística descriptiva',
  '¿Cuál es el precio promedio de las piezas de dos estrellas?',
  array['$4.000.', '$3.000.', '$2.000.', '$1.000.'],
  'Suma los precios de la misma columna y divide por la cantidad de tipos de pieza.', 'publicada', 'modelo', 'dfa4380e68cbb7d5c35b8efe75641b5b', 'baja';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('39bd7991-e03d-4256-9b5d-7d8eaa616bde', 1, 'Los tres precios son 4.000, 4.000 y 1.000. Su promedio es (4.000 + 4.000 + 1.000)/3 = 3.000 pesos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '1ad0917a-daab-444f-b5e7-e7c77c11b752', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'estadistica-descriptiva'),
  (select id from public.lotes where codigo = '2026-B'),
  '31652342-6983-4090-a23a-4acd6b1b77cc', 'Estadística descriptiva',
  '¿Qué relación tienen los cuartiles?',
  array['Q₂ es mayor que Q₁ y Q₁ es mayor que Q₃.', 'Q₂ es menor que Q₁ y Q₁ es mayor que Q₃.', 'Q₂ es mayor que Q₃ y menor que Q₁.', 'Q₂ es menor que Q₃ y mayor que Q₁.'],
  'Ubica los cuartiles en el 25 %, 50 % y 75 % de la lista.', 'publicada', 'modelo', '8fc0f42e7e2a05c4e9bc3cdfe1c975c3', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1ad0917a-daab-444f-b5e7-e7c77c11b752', 3, 'Por su ubicación en la lista ordenada, Q₁ < Q₂ < Q₃. Al ser distintos los datos, las posiciones de las tres partes dan valores estrictamente ordenados.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'd51515a0-76a0-4ee1-b0bb-45792b0dc62d', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'proporcionalidad'),
  (select id from public.lotes where codigo = '2026-B'),
  'e6a69195-bbfb-4272-99ff-115a1a2e5cb3', 'Proporcionalidad y porcentajes',
  '¿Cuánto recibe el tercer puesto?',
  array['2 millones.', '5 millones.', '10 millones.', '15 millones.'],
  'El resto también puede calcularse con 1 − 1/2 − 2/5.', 'publicada', 'modelo', 'b501b881c3f2bb0aacf87b8fa99aa467', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d51515a0-76a0-4ee1-b0bb-45792b0dc62d', 1, 'El primero recibe 25 millones y el segundo 20 millones. Quedan 50 − 25 − 20 = 5 millones.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '436754c7-10e4-4eb6-8034-9730358837d8', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'lectura-de-graficas'),
  (select id from public.lotes where codigo = '2026-B'),
  '4918dff0-ee76-4c7e-b236-ef803b1dfe8e', 'Interpretación de datos',
  '¿Qué pregunta NO puede resolverse con una parte de este proceso?',
  array['¿Con qué tipo de entrada se recaudó más dinero?', '¿Cuántas personas ingresaron en la semana?', '¿Cuál es la ganancia total del sitio turístico?', '¿Cuánto dinero se recaudó por tipo de entrada?'],
  'Ingreso es lo recaudado; ganancia es ingreso menos costos.', 'publicada', 'modelo', 'bb9af14c068e032cb67a9f100c85b723', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('436754c7-10e4-4eb6-8034-9730358837d8', 2, 'Los datos permiten calcular ingresos por entradas, pero la ganancia requiere restar costos y gastos, que no se conocen.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '5d6d1932-8286-4a8f-bc86-c0692ea51a66', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
  (select id from public.lotes where codigo = '2026-B'),
  '005488b9-895e-4997-a21b-cd8689c50d07', 'Áreas y perímetros',
  '¿Cuánto mide el ángulo entre la torre y el suelo indicado en la figura?',
  array['4°.', '140°.', '94°.', '86°.'],
  'Identifica si el ángulo pedido completa 90° o 180°.', 'publicada', 'modelo', '5d7238c26f3a03a2d56f7de90d3a9669', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5d6d1932-8286-4a8f-bc86-c0692ea51a66', 3, 'La vertical y el suelo forman 90°. El ángulo señalado es el complemento de 4°: 90° − 4° = 86°.');

