insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '64dd0667-6db1-48fc-a62b-22559aa85caa', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'ecuaciones-en-contexto'),
  (select id from public.lotes where codigo = '2026-B'),
  'fe48f504-a6c8-405d-8e8a-ad7fe9efb0f2', 'Ecuaciones en contexto',
  '¿Cómo deben repartirse las cuatro cajas para enviarlas en los dos aviones al mismo tiempo?',
  array['Avión 1: 8 y 2 toneladas. Avión 2: 7 y 5 toneladas.', 'Avión 1: 7 y 5 toneladas. Avión 2: 8 y 2 toneladas.', 'Avión 1: 8 y 5 toneladas. Avión 2: 7 y 2 toneladas.', 'Avión 1: 5 y 2 toneladas. Avión 2: 8 y 7 toneladas.'],
  'Comprueba la suma de cada avión, no solo el peso total.', 'publicada', 'modelo', '3f7ab3cb4bee0fdff54d2987bc8e7948', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('64dd0667-6db1-48fc-a62b-22559aa85caa', 1, 'Las cajas de 7 y 5 suman las 12 toneladas del avión 1. Las de 8 y 2 suman las 10 toneladas del avión 2. Las otras distribuciones exceden al menos una capacidad.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select 'd809fb79-de46-4087-974c-bf1975a0695a', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'areas-y-perimetros'),
  (select id from public.lotes where codigo = '2026-B'),
  '6cd24738-7ba4-4dc8-afca-0f8d8176fb27', 'Áreas y perímetros',
  '¿Qué valor es el más cercano a la distancia recorrida por la punta del minutero?',
  array['90 cm.', '95 cm.', '100 cm.', '105 cm.'],
  'El minutero da una vuelta cada hora; no lo confundas con la manecilla horaria.', 'publicada', 'modelo', '8faa76cf7fb196111084c312514e5394', 'media';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d809fb79-de46-4087-974c-bf1975a0695a', 1, 'El minutero completa tres vueltas en tres horas. Cada vuelta mide 2π×5 = 10π cm. El recorrido es 30π ≈ 94,25 cm, cuyo valor más cercano es 95 cm.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm, dificultad)
select '569e06b0-15a3-44f3-9311-ad406027c142', 'mat',
  (select id from public.temas where materia = 'mat' and codigo = 'funciones'),
  (select id from public.lotes where codigo = '2026-B'),
  '6aa2f392-6a3f-4812-abfe-8397c709daa3', 'Funciones y variación',
  'Alguien afirma que la razón número de profesores/número de alumnos aumentó de 2000 a 2010. ¿Es correcta la afirmación?',
  array['No, porque los cocientes inicial y final no se pueden comparar.', 'Sí, porque aumentó el número de profesores y disminuyó el de alumnos.', 'No, porque las variaciones son diferentes y el cociente permanece constante.', 'Sí, porque aumentaron tanto profesores como alumnos y los primeros crecieron más.'],
  'Compara primero numerador y denominador entre las dos fechas.', 'publicada', 'modelo', '2f4a9976efbe84963a7629e48de6ebf2', 'alta';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('569e06b0-15a3-44f3-9311-ad406027c142', 1, 'La razón pasa de 2.000/40.000 = 0,05 a 3.000/30.000 = 0,10. Un numerador mayor y un denominador menor hacen crecer el cociente positivo.');

